package com.leochaddad.capacitor.referrer;

import com.getcapacitor.JSObject;
import com.getcapacitor.Plugin;
import com.getcapacitor.PluginCall;
import com.getcapacitor.PluginMethod;
import com.getcapacitor.annotation.CapacitorPlugin;

@CapacitorPlugin(name = "CapacitorReferrer")
public class CapacitorReferrerPlugin extends Plugin {

    private CapacitorReferrer implementation = new CapacitorReferrer();

    @PluginMethod
    public void getReferrerDetails(PluginCall call) {
        implementation.getReferrerDetails(getContext(), new CapacitorReferrer.ReferrerCallback() {
            @Override
            public void onSuccess(JSObject result) {
                call.resolve(result);
            }

            @Override
            public void onError(String error) {
                call.reject(error);
            }
        });
    }
}
